	<script>
		// Function to scroll to cm7 element (by id or class)
		function scrollToCm7() {
			// Try to find by ID first
			const elementById = document.getElementById('cm7');
			if (elementById) {
				elementById.scrollIntoView({ behavior: 'smooth', block: 'start' });
				return;
			}
			
			// If not found by ID, try to find by class
			const elementByClass = document.querySelector('.cm7');
			if (elementByClass) {
				elementByClass.scrollIntoView({ behavior: 'smooth', block: 'start' });
				return;
			}
		}
		
		// Add click event listeners to all buttons
		document.addEventListener('DOMContentLoaded', function() {
			const buttons = document.querySelectorAll('.btn-primary, .btn-secondary');
			buttons.forEach(function(button) {
				button.addEventListener('click', scrollToCm7);
			});
		});
	</script>


