.logos-wrapper {
  width: 100%;
  overflow: hidden;
  position: relative;
}

.logos-wrapper::before,
.logos-wrapper::after {
  content: '';
  position: absolute;
  top: 0;
  bottom: 0;
  width: 100px;
  z-index: 10;
  pointer-events: none;
}

.logos-wrapper::before {
  left: 0;
  background: linear-gradient(to right, #f9fafb 0%, rgba(249, 250, 251, 0) 100%);
}

.logos-wrapper::after {
  right: 0;
  background: linear-gradient(to left, #f9fafb 0%, rgba(249, 250, 251, 0) 100%);
}

.logos-wrapper-bottom {
  width: 100%;
  overflow: hidden;
  position: relative;
}

.logos-wrapper-bottom::before,
.logos-wrapper-bottom::after {
  content: '';
  position: absolute;
  top: 0;
  bottom: 0;
  width: 100px;
  z-index: 10;
  pointer-events: none;
}

.logos-wrapper-bottom::before {
  left: 0;
  background: linear-gradient(to right, #f9fafb 0%, rgba(249, 250, 251, 0) 100%);
}

.logos-wrapper-bottom::after {
  right: 0;
  background: linear-gradient(to left, #f9fafb 0%, rgba(249, 250, 251, 0) 100%);
}

.logos-track {
  display: flex;
  width: fit-content;
  gap: 25px;
  animation: scroll-left 30s linear infinite;
}

.logos-track-bottom {
  display: flex;
  width: fit-content;
  gap: 25px;
  animation: scroll-right 30s linear infinite;
}

@keyframes scroll-left {
  0% { transform: translateX(0); }
  100% { transform: translateX(calc(-50%)); }
}

@keyframes scroll-right {
  0% { transform: translateX(calc(-50%)); }
  100% { transform: translateX(0); }
}

