        let currentTab = 'marketing-engagement';
        let currentPage = 0;
  
        // Initialize
        function initTabs() {
            const tabs = useCaseSection.querySelectorAll('.use-case-tab-button[data-tab]');
            tabs.forEach(tab => {
                tab.addEventListener('click', () => {
                    const tabId = tab.getAttribute('data-tab');
                    switchTab(tabId);
        });
      });
      
            const prevButton = useCaseSection.querySelector('#use-case-prev-button');
            const nextButton = useCaseSection.querySelector('#use-case-next-button');
            
            if (prevButton) {
                prevButton.addEventListener('click', () => {
                    navigatePage(-1);
                });
            }
  
            if (nextButton) {
                nextButton.addEventListener('click', () => {
                    navigatePage(1);
                });
            }
  
            // Match content box width to tabs navbar width
            syncContentBoxWidth();
            updateContent();
        }
  
        function syncContentBoxWidth() {
            // Don't constrain width - let it use natural width from CSS
            const contentBox = useCaseSection.querySelector('#use-case-content-box');
            if (contentBox) {
                contentBox.style.width = '';
                contentBox.style.maxWidth = '';
            }
        }
  
        function switchTab(tabId) {
            currentTab = tabId;
            currentPage = 0;
  
            // Update tab styles - only toggle active class, don't change anything else
            const tabs = useCaseSection.querySelectorAll('.use-case-tab-button[data-tab]');
            tabs.forEach(tab => {
                const isActive = tab.getAttribute('data-tab') === tabId;
                if (isActive) {
                    tab.classList.add('active');
      } else {
                    tab.classList.remove('active');
                }
            });
  
            updateContent();
        }
  
        function navigatePage(direction) {
            const pages = getCurrentPages();
            if (!pages || pages.length <= 1) return;
  
            currentPage += direction;
  
            if (currentPage < 0) {
                currentPage = pages.length - 1;
            } else if (currentPage >= pages.length) {
                currentPage = 0;
            }
  
            updateContent();
        }
  
        function getCurrentPages() {
            const content = tabData[currentTab];
            if (!content) return null;
            
            // If it's an array, return it; if it's an object, wrap it in an array
            return Array.isArray(content) ? content : [content];
        }
  
        function updateContent() {
            const pages = getCurrentPages();
            if (!pages || !pages[currentPage]) return;
  
            const content = pages[currentPage];
            const navButtons = useCaseSection.querySelector('#use-case-nav-buttons');
            
            // Show/hide navigation buttons based on whether there are multiple pages
            if (navButtons) {
                if (pages.length > 1) {
                    navButtons.style.display = 'flex';
                } else {
                    navButtons.style.display = 'none';
                }
            }
            
            const headingEl = useCaseSection.querySelector('#use-case-tab-heading');
            const descriptionEl = useCaseSection.querySelector('#use-case-tab-description');
            const impactEl = useCaseSection.querySelector('#use-case-tab-impact');
            const imageEl = useCaseSection.querySelector('#use-case-tab-image');
            const labelEl = useCaseSection.querySelector('#use-case-tab-label');
            
            if (headingEl) headingEl.textContent = content.heading || '';
            if (descriptionEl) descriptionEl.textContent = content.description || '';
            if (impactEl) {
                if (content.impact) {
                    impactEl.textContent = content.impact;
                    impactEl.style.display = 'block';
                } else {
                    impactEl.style.display = 'none';
                }
            }
            if (imageEl && content.image) imageEl.src = content.image;
            if (labelEl) labelEl.textContent = content.label || '';
            
            // On desktop/tablet, ensure the description never overlaps the title:
            // dynamically position the description below the heading with a fixed gap.
            if (headingEl && descriptionEl) {
                // Use requestAnimationFrame to ensure layout is recalculated
                requestAnimationFrame(() => {
                    if (window.innerWidth > 768) {
                        // Use the heading's rendered height to place description underneath
                        const headingTop = headingEl.offsetTop;
                        const headingHeight = headingEl.offsetHeight;
                        const gap = 16; // pixels of space between title and description
                        const newTop = headingTop + headingHeight + gap;
                        descriptionEl.style.top = newTop + 'px';
                    } else {
                        // Let mobile layout control positioning
                        descriptionEl.style.top = '';
                    }
                });
            }
        }
  
        // Initialize when DOM is ready
        if (document.readyState === 'loading') {
            document.addEventListener('DOMContentLoaded', initTabs);
        } else {
            initTabs();
        }
        
        // Sync width on window resize
        window.addEventListener('resize', () => {
            syncContentBoxWidth();
            // Re-adjust spacing between title and description when viewport changes
            const headingEl = useCaseSection.querySelector('#use-case-tab-heading');
            const descriptionEl = useCaseSection.querySelector('#use-case-tab-description');
            if (headingEl && descriptionEl) {
                requestAnimationFrame(() => {
                    if (window.innerWidth > 768) {
                        const headingTop = headingEl.offsetTop;
                        const headingHeight = headingEl.offsetHeight;
                        const gap = 16;
                        const newTop = headingTop + headingHeight + gap;
                        descriptionEl.style.top = newTop + 'px';
                    } else {
                        descriptionEl.style.top = '';
                    }
                });
            }
        });
    })();
  </script>				</div>
