<div class="faq-section">
    <div class="faq-container">
        <div class="faq-content">
            <div class="faq-header-frame">
                <div class="faq-subheading"> FAQ </div>
                <div class="faq-heading"> Got Questions About Orbit? </div>
                <div class="faq-answer" style="max-height: 500px; opacity: 1; margin-top: 0; text-align: center !important;"> Everything you need to know to get started. </div>
            </div>
        </div>
    </div>
    <div class="faq-container-wrapper">
        <div class="faq-content-wrapper">
            <div class="faq-item">
                <div class="faq-content-row">
                    <div class="faq-text-wrapper">
                        <div class="faq-question"> What is Orbit? </div>
                        <div class="faq-answer"> Orbit is a multi-channel customer engagement platform that unifies SMS, WhatsApp, Email, Voice, Push Notifications, and Social Messaging in one system. Through a single dashboard you can launch campaigns, automate workflows, and track performance across all communication channels. </div>
                    </div><svg class="faq-icon" width="24" height="24" viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg">
                        <path d="M6 9L12 15L18 9" stroke="var(--text-text-quaternary, #62748e)" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" />
                    </svg>
                </div>
            </div>
            <div class="faq-item">
                <div class="faq-content-row">
                    <div class="faq-text-wrapper">
                        <div class="faq-question"> How quickly can we start sending messages? </div>
                        <div class="faq-answer"> Once you sign up, we'll provide you with a demo account so you can start testing immediately while we handle the setup process and migration of your existing numbers and channels. </div>
                    </div><svg class="faq-icon" width="24" height="24" viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg">
                        <path d="M6 9L12 15L18 9" stroke="var(--text-text-quaternary, #62748e)" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" />
                    </svg>
                </div>
            </div>
            <div class="faq-item">
                <div class="faq-content-row">
                    <div class="faq-text-wrapper">
                        <div class="faq-question"> Do you have a minimum monthly commitment? </div>
                        <div class="faq-answer"> No. You can send as many messages as you need with no minimums or maximums. </div>
                    </div><svg class="faq-icon" width="24" height="24" viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg">
                        <path d="M6 9L12 15L18 9" stroke="var(--text-text-quaternary, #62748e)" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" />
                    </svg>
                </div>
            </div>
            <div class="faq-item">
                <div class="faq-content-row">
                    <div class="faq-text-wrapper">
                        <div class="faq-question"> Can we use our existing sender IDs for SMS and WhatsApp? </div>
                        <div class="faq-answer"> Yes. You can bring existing SMS sender IDs and WhatsApp Business accounts. We'll help with registration if you need new sender IDs in specific countries. </div>
                    </div><svg class="faq-icon" width="24" height="24" viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg">
                        <path d="M6 9L12 15L18 9" stroke="var(--text-text-quaternary, #62748e)" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" />
                    </svg>
                </div>
            </div>
            <div class="faq-item">
                <div class="faq-content-row">
                    <div class="faq-text-wrapper">
                        <div class="faq-question"> What happens if one channel fails? </div>
                        <div class="faq-answer"> You can set fallback logic for each communication. For example, if WhatsApp fails, the message is automatically sent via SMS. You can configure unlimited fallback chains in the platform. </div>
                    </div><svg class="faq-icon" width="24" height="24" viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg">
                        <path d="M6 9L12 15L18 9" stroke="var(--text-text-quaternary, #62748e)" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" />
                    </svg>
                </div>
            </div>
            <div class="faq-item">
                <div class="faq-content-row">
                    <div class="faq-text-wrapper">
                        <div class="faq-question"> Can we migrate from our current provider? </div>
                        <div class="faq-answer"> Absolutely. We offer white-glove migration support with zero downtime. Most migrations are completed in 3 to 5 days depending on complexity. We'll help migrate contact lists, message templates, and historical data. </div>
                    </div><svg class="faq-icon" width="24" height="24" viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg">
                        <path d="M6 9L12 15L18 9" stroke="var(--text-text-quaternary, #62748e)" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" />
              </svg>
        </div>
            </div>
            
            <div class="faq-item">
                <div class="faq-content-row">
                    <div class="faq-text-wrapper">
                        <div class="faq-question"> Do you offer technical support? </div>
                        <div class="faq-answer"> Yes. We provide 24/7 support via phone, email, and chat for all customers. Enterprise clients also get dedicated customer success managers. </div>
                    </div><svg class="faq-icon" width="24" height="24" viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg">
                        <path d="M6 9L12 15L18 9" stroke="var(--text-text-quaternary, #62748e)" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" />
              </svg>
            </div>
          </div>
            <div class="faq-item">
                <div class="faq-content-row">
                    <div class="faq-text-wrapper">
                        <div class="faq-question"> Can Orbit integrate with our CRM and e-commerce platform? </div>
                        <div class="faq-answer"> We have 500+ pre-built integrations including Salesforce, Airtable HubSpot, Shopify, and WooCommerce. Custom integrations are available for enterprise customers. Our REST API makes integration straightforward. </div>
                    </div><svg class="faq-icon" width="24" height="24" viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg">
                        <path d="M6 9L12 15L18 9" stroke="var(--text-text-quaternary, #62748e)" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" />
                    </svg>
        </div>
            </div>
            <div class="faq-item">
                <div class="faq-content-row">
                    <div class="faq-text-wrapper">
                        <div class="faq-question"> What's your deliverability rate? </div>
                        <div class="faq-answer"> Average deliverability of 99% across all channels. For critical transactional messages (OTPs, confirmations), we achieve 99.9% deliverability through smart routing and direct carrier connections. </div>
                    </div><svg class="faq-icon" width="24" height="24" viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg">
                        <path d="M6 9L12 15L18 9" stroke="var(--text-text-quaternary, #62748e)" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" />
                    </svg>
        </div>
            </div>
            <div class="faq-item">
                <div class="faq-content-row">
                    <div class="faq-text-wrapper">
                        <div class="faq-question"> What are the Terms and Conditions for using Devotel's Orbit? </div>
                        <div class="faq-answer"> Our full <a href="https://devotel.com/products/platforms/orbit/terms-and-conditions/" target="_blank" rel="noopener noreferrer">Terms and Conditions</a> outline the rights, responsibilities, and guidelines for using Devotel's Orbit. You can review our Privacy Policy in detail <a href="https://devotel.com/products/platforms/orbit/privacy-policy/" target="_blank" rel="noopener noreferrer">here</a>. If you have specific questions about our terms, feel free to contact our team. </div>
                    </div><svg class="faq-icon" width="24" height="24" viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg">
                        <path d="M6 9L12 15L18 9" stroke="var(--text-text-quaternary, #62748e)" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" />
                    </svg>
            </div>
            </div>
        </div>
    </div>
</div>
<script>
    (function() {
        // Scoped to prevent conflicts
        const faqSection = document.querySelector('.faq-section');
        if (!faqSection) return;
        
        const faqItems = faqSection.querySelectorAll('.faq-item');
        
        faqItems.forEach(function(item) {
            item.addEventListener('click', function() {
                // Toggle the 'open' class
                const isOpen = item.classList.contains('open');
                
                if (isOpen) {
                    item.classList.remove('open');
                } else {
                    item.classList.add('open');
                }
            });
        });
    })();
</script>
