<script>
		// Scroll to cm7 element when button is clicked
    document.addEventListener('DOMContentLoaded', function() {
			const button = document.getElementById('scroll-to-cm7-btn');
			if (button) {
				button.addEventListener('click', function(e) {
					e.preventDefault();
					
					// Try to find element by ID first, then by class
					let targetElement = document.getElementById('cm7');
					if (!targetElement) {
						targetElement = document.querySelector('.cm7');
					}
					
					if (targetElement) {
						// Smooth scroll to the element
						targetElement.scrollIntoView({
							behavior: 'smooth',
							block: 'start'
						});
					} else {
						console.warn('Element with id "cm7" or class "cm7" not found');
					}
				});
			}
    });
</script>


